import type { TabBarProps } from "./tab-bar.types";

import React, { forwardRef } from "react";
import * as RadixTabs from "@radix-ui/react-tabs";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { useUniqueId } from "@system";

import { TabBarClasses, StyledTabBar } from "./tab-bar.styles";
import { TabBarContext } from "./hooks/use-tab-bar";
import { useTabBarManager } from "./hooks/use-tab-bar-manager";
import { TabBarList, TabBarPanel, TabBarAddTab } from "./subcomponents";

type TabBarComponent = React.ForwardRefExoticComponent<
  TabBarProps & React.RefAttributes<HTMLDivElement>
> & {
  List: typeof TabBarList;
  Panel: typeof TabBarPanel;
  AddTab: typeof TabBarAddTab;
};

const TabBar = forwardRef<HTMLDivElement, TabBarProps & RadixTabs.TabsProps>(
  (
    {
      className,
      variant = "default",
      size = "default",
      children,
      defaultValue,
      rememberActiveTab = false,
      uniqueId,
      onValueChange,
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(TabBarClasses.root, size === "sm" && TabBarClasses.sm, className);
    const addTabId = useUniqueId("add-tab");
    const { activeTab, setActiveTab } = useTabBarManager(
      defaultValue,
      rememberActiveTab,
      uniqueId,
      onValueChange,
      addTabId,
    );

    return (
      <TabBarContext.Provider value={{ activeTab, setActiveTab, variant, size, addTabId }}>
        <StyledTabBar
          ref={ref}
          className={rootClasses}
          currentTheme={theme}
          defaultValue={defaultValue}
          value={activeTab}
          variant={variant}
          onValueChange={setActiveTab}
          {...props}
        >
          {children}
        </StyledTabBar>
      </TabBarContext.Provider>
    );
  },
) as TabBarComponent;

TabBar.displayName = "TabBar";

TabBar.List = TabBarList;
TabBar.Panel = TabBarPanel;
TabBar.AddTab = TabBarAddTab;

export default TabBar;
